// SPENDING ANALYSIS — and the one thing it exists to get right: A TRANSFER IS NOT SPENDING.
//
// Paying $300 from chequing to a credit card looks exactly like a $300 outflow. It is not
// consumption — it is the same money in a different place, and the card minimum is ALREADY on the
// obligation calendar. Counting it here as well subtracts it twice from the runway, which shortens
// the answer in a way that looks like prudence and is simply wrong. Moving money between your own
// accounts is the same mistake with no upside at all.
//
// So outflows are classified before anything is totalled: PAIRED (an outflow matched by an inflow of
// the same size on another account within a few days), DEBT (a payment to an account declared as a
// debt), FIXED (matched to a detected recurring charge), or VARIABLE. Only variable spending is
// discretionary, and `discretionaryMonthly` is the figure `runway` asks for.
//
// CATEGORISATION IS DATA, DETERMINISTIC, AND LOCAL. A table of keywords, not a model — a model here
// would mean sending somebody's merchant list somewhere. What it cannot place is reported as
// UNCATEGORISED rather than dropped into an "other" bucket, because a large "other" is a finding and
// a large "uncategorised" is an admission.
import { type Money, money, sum } from "@/features/finance/lib/money";
import { type Txn, daysBetween, merchantKey, monthOf } from "@/features/finance/lib/txn";
import type { Recurring } from "@/features/finance/lib/recurring";
import { type ReconciledLedger, covered } from "@/features/finance/lib/reconcile";
import type { Position } from "@/features/finance/lib/position";

/** Why an outflow is or is not discretionary spending. */
export type OutflowClass = "paired" | "debt" | "fixed" | "variable";

export interface ClassifiedOutflow {
  readonly txn: Txn;
  readonly kind: OutflowClass;
  /** Present for `variable` and `fixed`; undefined means nothing in the table matched. */
  readonly category?: string;
  /** For `paired`, the transaction on the other side. */
  readonly counterpart?: Txn;
  /** For `fixed`, the recurring charge it belongs to. */
  readonly recurring?: string;
}

export interface CategoryTotal {
  readonly category: string;
  readonly total: Money;
  readonly count: number;
  /** Median across the whole months observed — the usual month for this category. */
  readonly typicalMonth: Money;
}

export interface SpendingAnalysis {
  readonly from: string;
  readonly to: string;
  /** WHOLE months the medians are computed over. */
  readonly monthsObserved: number;
  readonly outflows: readonly ClassifiedOutflow[];
  /** Standing charges — rent, subscriptions, insurance. Not a choice this month. */
  readonly fixedMonthly: Money;
  /** Everything else that was actually consumed. What `runway` wants. */
  readonly variableMonthly: Money;
  readonly categories: readonly CategoryTotal[];
  /**
   * The same totals over VARIABLE outflows only.
   *
   * `categories` covers everything that was spent, fixed charges included, because "where does my
   * money go" wants rent in the answer. Anything downstream that ALSO counts the obligation calendar
   * must use this one instead — rent appears in both, and adding them counts it twice. That is not
   * hypothetical: `viable` did exactly that and overstated every tier by the whole of the rent.
   */
  readonly variableCategories: readonly CategoryTotal[];
  /** Money that MOVED rather than left. Named so the exclusion is visible, never silent. */
  readonly transferred: Money;
  readonly transferCount: number;
  /** Payments to declared debts, excluded because the calendar already has them. */
  readonly debtPayments: Money;
  /** Outflows nothing in the table could place. Reported, never bucketed as "other". */
  readonly uncategorised: readonly Txn[];
  readonly notes: readonly string[];
}

/**
 * The category table. DATA, so it can be read, argued with and extended without touching logic.
 * First match wins, so the order is meaningful: fuel before transport, groceries before shopping.
 */
export const CATEGORY_RULES: readonly { readonly category: string; readonly match: readonly string[] }[] = [
  { category: "housing", match: ["rent", "mortgage", "landlord", "property mgmt", "hoa"] },
  { category: "utilities", match: ["electric", "power", "gas company", "water", "sewer", "internet", "broadband", "mobile", "wireless", "phone"] },
  { category: "insurance", match: ["insurance", "assurance", "geico", "allstate"] },
  { category: "healthcare", match: ["pharmacy", "dental", "clinic", "medical", "hospital", "optical", "vision"] },
  { category: "childcare", match: ["daycare", "childcare", "nursery", "preschool"] },
  { category: "education", match: ["tuition", "university", "college", "student loan", "bookstore"] },
  { category: "fuel", match: ["shell", "chevron", "exxon", "bp", "texaco", "fuel", "petrol", "gas station"] },
  { category: "transport", match: ["uber", "lyft", "transit", "metro", "parking", "toll", "rail", "airline", "airlines"] },
  { category: "groceries", match: ["grocery", "market", "supermarket", "safeway", "kroger", "aldi", "trader", "whole foods", "food store"] },
  { category: "dining", match: ["restaurant", "cafe", "coffee", "pizza", "grill", "diner", "bar", "brewing", "doordash", "grubhub", "seamless"] },
  { category: "subscriptions", match: ["netflix", "spotify", "hulu", "prime", "membership", "subscription", "patreon"] },
  { category: "entertainment", match: ["cinema", "theatre", "theater", "concert", "steam", "playstation", "xbox", "nintendo"] },
  { category: "shopping", match: ["amzn", "amazon", "target", "walmart", "costco", "store", "shop", "retail"] },
  { category: "fees", match: ["fee", "interest", "overdraft", "service charge", "atm"] },
  { category: "cash", match: ["withdrawal", "cash", "atm withdrawal"] },
];

/** The category a description falls in, or UNDEFINED — which is not the same as "other". */
export function categorise(description: string): string | undefined {
  const text = description.toLowerCase();
  return CATEGORY_RULES.find((r) => r.match.some((m) => text.includes(m)))?.category;
}

export interface SpendingOptions {
  /** How far apart the two halves of an internal transfer may be dated. */
  readonly transferWindowDays?: number;
}

const median = (xs: number[]): number => {
  if (!xs.length) return 0;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
};

/** The months a median may be taken over: whole ones only, dropping a partial at either end. */
function wholeMonths(dates: readonly string[]): string[] {
  const months = [...new Set(dates.map(monthOf))].sort();
  return months.length > 2 ? months.slice(1, -1) : months;
}

export function analyseSpending(
  ledger: ReconciledLedger,
  position: Position | undefined,
  recurring: readonly Recurring[],
  currency: string,
  opts: SpendingOptions = {},
): SpendingAnalysis {
  const { transferWindowDays = 3 } = opts;
  const rows = covered(ledger);
  const outflowRows = rows.filter((t) => t.amount.minor < 0);
  const inflowRows = rows.filter((t) => t.amount.minor > 0);
  const notes: string[] = [];

  // PAIRING FIRST. An outflow matched by an inflow of the same size on ANOTHER account within a few
  // days is money that moved, not money that left. Each inflow can be claimed once — otherwise two
  // identical outflows both match one deposit and one of them is wrongly excluded.
  const takenInflow = new Set<Txn>();
  const pairOf = new Map<Txn, Txn>();
  for (const out of outflowRows) {
    const hit = inflowRows.find(
      (i) =>
        !takenInflow.has(i) &&
        i.account !== out.account &&
        i.amount.minor === -out.amount.minor &&
        Math.abs(daysBetween(out.date, i.date)) <= transferWindowDays,
    );
    if (hit) {
      takenInflow.add(hit);
      pairOf.set(out, hit);
    }
  }

  const debtAccounts = new Set((position?.accounts ?? []).filter((a) => a.isDebt).map((a) => a.account));
  const debtNames = (position?.accounts ?? [])
    .filter((a) => a.isDebt)
    .map((a) => a.institution.toLowerCase())
    .filter(Boolean);

  const recurringKeys = new Map(recurring.map((r) => [`${r.account}\0${r.key}`, r.label]));

  const outflows: ClassifiedOutflow[] = outflowRows.map((txn) => {
    const counterpart = pairOf.get(txn);
    if (counterpart) return { txn, kind: "paired", counterpart };

    // A payment to a card the ledger does not contain has no inflow to pair with, so the only
    // remaining signal is the institution's own name in the description.
    const text = txn.description.toLowerCase();
    if (debtAccounts.has(txn.account) === false && debtNames.some((n) => text.includes(n))) {
      return { txn, kind: "debt" };
    }

    const key = `${txn.account}\0${merchantKey(txn.description)}`;
    const label = recurringKeys.get(key);
    if (label) return { txn, kind: "fixed", category: categorise(txn.description), recurring: label };

    return { txn, kind: "variable", category: categorise(txn.description) };
  });

  const spent = outflows.filter((o) => o.kind === "fixed" || o.kind === "variable");
  const months = wholeMonths(spent.map((o) => o.txn.date));
  const monthSet = new Set(months);

  const perMonth = (rowsIn: readonly ClassifiedOutflow[]): number => {
    const totals = months.map((m) =>
      rowsIn.filter((o) => monthOf(o.txn.date) === m).reduce((n, o) => n + -o.txn.amount.minor, 0),
    );
    return median(totals);
  };

  const inWholeMonths = spent.filter((o) => monthSet.has(monthOf(o.txn.date)));
  const byCategory = new Map<string, ClassifiedOutflow[]>();
  for (const o of inWholeMonths) {
    if (!o.category) continue;
    const b = byCategory.get(o.category);
    if (b) b.push(o);
    else byCategory.set(o.category, [o]);
  }

  const byVariableCategory = new Map<string, ClassifiedOutflow[]>();
  for (const o of inWholeMonths) {
    if (!o.category || o.kind !== "variable") continue;
    const b = byVariableCategory.get(o.category);
    if (b) b.push(o);
    else byVariableCategory.set(o.category, [o]);
  }

  const uncategorised = inWholeMonths.filter((o) => !o.category).map((o) => o.txn);
  if (uncategorised.length) {
    const share = Math.round((uncategorised.length / Math.max(1, inWholeMonths.length)) * 100);
    notes.push(
      `${uncategorised.length} outflow(s) — ${share}% of them — matched no category rule and are listed rather than bucketed as "other"; the category totals below do not add up to the monthly figures because of it`,
    );
  }
  if (months.length < 3) {
    notes.push(`only ${months.length} whole month(s) here — a median over that is a description of those months, not a pattern`);
  }

  const transfers = outflows.filter((o) => o.kind === "paired");
  const debts = outflows.filter((o) => o.kind === "debt");
  if (transfers.length) {
    notes.push(
      `${transfers.length} outflow(s) were matched to an inflow elsewhere and are EXCLUDED — moving money between your own accounts is not spending`,
    );
  }
  if (debts.length) {
    notes.push(
      `${debts.length} payment(s) to a declared debt are EXCLUDED — the obligation calendar already carries them, and counting them here would subtract the same money twice`,
    );
  }

  return {
    from: rows[0]?.date ?? ledger.through,
    to: ledger.through,
    monthsObserved: months.length,
    outflows,
    fixedMonthly: money(perMonth(spent.filter((o) => o.kind === "fixed")), currency),
    variableMonthly: money(perMonth(spent.filter((o) => o.kind === "variable")), currency),
    categories: [...byCategory.entries()]
      .map(([category, os]) => ({
        category,
        total: sum(os.map((o) => money(-o.txn.amount.minor, currency)), currency),
        count: os.length,
        typicalMonth: money(perMonth(os), currency),
      }))
      .sort((a, b) => b.total.minor - a.total.minor),
    variableCategories: [...byVariableCategory.entries()]
      .map(([category, os]) => ({
        category,
        total: sum(os.map((o) => money(-o.txn.amount.minor, currency)), currency),
        count: os.length,
        typicalMonth: money(perMonth(os), currency),
      }))
      .sort((a, b) => b.total.minor - a.total.minor),
    transferred: sum(transfers.map((o) => money(-o.txn.amount.minor, currency)), currency),
    transferCount: transfers.length,
    debtPayments: sum(debts.map((o) => money(-o.txn.amount.minor, currency)), currency),
    uncategorised,
    notes,
  };
}

/**
 * The figure `runway` asks for: what an ordinary month costs beyond the standing obligations.
 *
 * Fixed spending is deliberately NOT included — the obligation calendar already carries it, and a
 * runway that subtracted both would double-count every subscription it knows about.
 */
export const discretionaryMonthly = (s: SpendingAnalysis): Money => s.variableMonthly;

/** Where the variable money actually goes, biggest first — the list to act on. */
export const topCategories = (s: SpendingAnalysis, n = 5): readonly CategoryTotal[] => s.categories.slice(0, n);

