import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { Txn } from "@/features/finance/lib/txn";
import type { Recurring } from "@/features/finance/lib/recurring";
import type { AccountPosition, Position } from "@/features/finance/lib/position";
import { unverifiedLedger } from "@/features/finance/lib/reconcile";
import {
  CATEGORY_RULES,
  analyseSpending,
  categorise,
  discretionaryMonthly,
  topCategories,
} from "@/features/finance/lib/spending";

// SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");
const tx = (date: string, description: string, major: number, account = "checking"): Txn => ({
  date,
  description,
  amount: usd(major),
  account,
});

const ledger = (txns: Txn[], through = "2026-06-30") => unverifiedLedger(txns, through, "synthetic fixture");

const card: AccountPosition = {
  account: "card",
  institution: "Northwind Card",
  kind: "credit",
  balance: usd(-2000),
  asOf: "2026-06-30",
  rolledForward: 0,
  isDebt: true,
  owed: usd(2000),
};

const positionWith = (accounts: AccountPosition[]): Position => ({
  asOf: "2026-06-30",
  currency: "USD",
  accounts,
  netWorth: usd(0),
  liquid: usd(0),
  totalDebt: usd(0),
  dailyInterest: usd(0),
  minimumsDue: usd(0),
  complete: true,
  problems: [],
  provenance: "synthetic",
});

const rent: Recurring = {
  key: "rent landlord",
  label: "RENT",
  account: "checking",
  cadence: "monthly",
  typical: usd(1500),
  annualised: usd(18000),
  occurrences: 6,
  firstSeen: "2026-01-01",
  lastSeen: "2026-06-01",
  regularity: 1,
  amountStability: 1,
  lapsed: false,
};

/** FIVE months, so THREE are whole. With only two, a median of an even set is the mean — and a
 *  median that is a mean cannot demonstrate the thing the median is there for. */
const months = ["2026-02", "2026-03", "2026-04", "2026-05", "2026-06"];
const groceries = months.flatMap((m) => [tx(`${m}-08`, "SAFEWAY GROCERY", -200), tx(`${m}-22`, "SAFEWAY GROCERY", -200)]);
const rentRows = months.map((m) => tx(`${m}-01`, "RENT PAYMENT LANDLORD", -1500));

describe("categorise — a table, not a model", () => {
  it("places the obvious things", () => {
    expect(categorise("SAFEWAY GROCERY #221")).toBe("groceries");
    expect(categorise("SHELL OIL 4471")).toBe("fuel");
    expect(categorise("UBER TRIP")).toBe("transport");
    expect(categorise("NETFLIX.COM")).toBe("subscriptions");
    expect(categorise("RENT PAYMENT LANDLORD")).toBe("housing");
  });

  it("returns UNDEFINED for what it cannot place — not 'other'", () => {
    // A large "other" is a finding; a large "uncategorised" is an admission. They are different
    // claims and this module only makes the honest one.
    expect(categorise("ZZQ HOLDINGS 8871")).toBeUndefined();
    expect(CATEGORY_RULES.some((r) => r.category === "other")).toBe(false);
  });

  it("takes the FIRST matching rule, so order is meaningful", () => {
    // "gas station" is fuel, not utilities, even though "gas company" is in the utilities rule.
    expect(categorise("QUIK GAS STATION")).toBe("fuel");
    const fuelAt = CATEGORY_RULES.findIndex((r) => r.category === "fuel");
    const shoppingAt = CATEGORY_RULES.findIndex((r) => r.category === "shopping");
    expect(fuelAt).toBeLessThan(shoppingAt);
  });
});

describe("analyseSpending — A TRANSFER IS NOT SPENDING", () => {
  it("excludes an outflow matched by an inflow on another account", () => {
    // $300 chequing → card is the same money in a different place. Counting it as spending, while
    // the card minimum is already on the obligation calendar, subtracts it from the runway twice.
    const rows = [
      ...groceries,
      tx("2026-04-10", "PAYMENT TO CARD", -300, "checking"),
      tx("2026-04-11", "PAYMENT RECEIVED THANK YOU", 300, "card"),
    ];
    const s = analyseSpending(ledger(rows), undefined, [], "USD");
    expect(s.transferCount).toBe(1);
    expect(s.transferred.minor).toBe(usd(300).minor);
    expect(s.outflows.find((o) => o.txn.description === "PAYMENT TO CARD")!.kind).toBe("paired");
    // April's variable spend is the two grocery runs and nothing else.
    expect(s.variableMonthly.minor).toBe(usd(400).minor);
    expect(s.notes.join(" ")).toContain("not spending");
  });

  it("will not pair an outflow with an inflow on the SAME account", () => {
    const rows = [...groceries, tx("2026-04-10", "MOVE", -300), tx("2026-04-11", "MOVE BACK", 300)];
    const s = analyseSpending(ledger(rows), undefined, [], "USD");
    expect(s.transferCount).toBe(0);
  });

  it("will not pair across a gap wider than the window", () => {
    const rows = [
      ...groceries,
      tx("2026-04-01", "PAYMENT TO CARD", -300, "checking"),
      tx("2026-04-20", "PAYMENT RECEIVED", 300, "card"),
    ];
    expect(analyseSpending(ledger(rows), undefined, [], "USD").transferCount).toBe(0);
    expect(analyseSpending(ledger(rows), undefined, [], "USD", { transferWindowDays: 30 }).transferCount).toBe(1);
  });

  it("claims each inflow ONCE, so two identical outflows do not both match one deposit", () => {
    const rows = [
      ...groceries,
      tx("2026-04-10", "PAYMENT TO CARD", -300, "checking"),
      tx("2026-04-10", "SOME MERCHANT", -300, "checking"),
      tx("2026-04-11", "PAYMENT RECEIVED", 300, "card"),
    ];
    const s = analyseSpending(ledger(rows), undefined, [], "USD");
    expect(s.transferCount).toBe(1);
    expect(s.outflows.filter((o) => o.kind === "variable" && o.txn.amount.minor === usd(-300).minor)).toHaveLength(1);
  });

  it("excludes a payment to a declared debt even with no inflow to pair against", () => {
    // The card is not in the ledger, so there is no other side to match. The institution's own name
    // in the description is the only signal left, and the calendar already carries the minimum.
    const rows = [...groceries, tx("2026-04-10", "NORTHWIND CARD PAYMENT", -300)];
    const s = analyseSpending(ledger(rows), positionWith([card]), [], "USD");
    expect(s.debtPayments.minor).toBe(usd(300).minor);
    expect(s.variableMonthly.minor).toBe(usd(400).minor);
    expect(s.notes.join(" ")).toContain("subtract the same money twice");
  });
});

describe("analyseSpending — fixed is not discretionary", () => {
  const s = () => analyseSpending(ledger([...groceries, ...rentRows]), undefined, [rent], "USD");

  it("separates a detected recurring charge from what was actually chosen this month", () => {
    expect(s().fixedMonthly.minor).toBe(usd(1500).minor);
    expect(s().variableMonthly.minor).toBe(usd(400).minor);
    const fixed = s().outflows.filter((o) => o.kind === "fixed");
    expect(fixed).toHaveLength(5);
    expect(fixed[0].recurring).toBe("RENT");
  });

  it("gives runway ONLY the variable half, because the calendar already has the fixed half", () => {
    // A runway subtracting both would double-count every subscription it knows about.
    expect(discretionaryMonthly(s()).minor).toBe(s().variableMonthly.minor);
    expect(discretionaryMonthly(s()).minor).not.toBe(s().fixedMonthly.minor + s().variableMonthly.minor);
  });

  it("treats the same merchant on a DIFFERENT account as variable", () => {
    const elsewhere = analyseSpending(
      ledger([...groceries, ...rentRows.map((t) => ({ ...t, account: "other" }))]),
      undefined,
      [rent],
      "USD",
    );
    expect(elsewhere.outflows.filter((o) => o.kind === "fixed")).toHaveLength(0);
  });
});

describe("analyseSpending — medians, whole months, and what it will not claim", () => {
  it("takes a MEDIAN over whole months, so one heavy month does not set the baseline", () => {
    const withSpike = [...groceries, tx("2026-04-15", "TARGET STORE", -3000)];
    const s = analyseSpending(ledger(withSpike), undefined, [], "USD");
    // March, April and May are whole; April carries a $3,000 spike. The mean would be $1,400.
    expect(s.monthsObserved).toBe(3);
    expect(s.variableMonthly.minor).toBe(usd(400).minor);
  });

  it("says when there are too few whole months for a median to be a pattern", () => {
    const s = analyseSpending(ledger([tx("2026-06-08", "SAFEWAY GROCERY", -200)]), undefined, [], "USD");
    expect(s.notes.join(" ")).toContain("not a pattern");
  });

  it("lists what it could not categorise, and says the totals will not add up because of it", () => {
    const rows = [...groceries, ...months.map((m) => tx(`${m}-12`, "ZZQ HOLDINGS 8871", -125))];
    const s = analyseSpending(ledger(rows), undefined, [], "USD");
    expect(s.uncategorised.map((t) => t.description)).toEqual(["ZZQ HOLDINGS 8871", "ZZQ HOLDINGS 8871", "ZZQ HOLDINGS 8871"]);
    expect(s.notes.join(" ")).toContain("do not add up");
    // It is still counted in the monthly figure — unplaceable is not the same as absent — but it is
    // absent from the category totals, which is exactly what the note warns about.
    expect(s.variableMonthly.minor).toBe(usd(525).minor);
    expect(s.categories.reduce((n, c) => n + c.typicalMonth.minor, 0)).toBe(usd(400).minor);
  });

  it("ranks categories by what they actually cost", () => {
    const rows = [...groceries, ...months.flatMap((m) => [tx(`${m}-14`, "CORNER CAFE", -30)])];
    const top = topCategories(analyseSpending(ledger(rows), undefined, [], "USD"));
    expect(top.map((c) => c.category)).toEqual(["groceries", "dining"]);
    expect(top[0].typicalMonth.minor).toBe(usd(400).minor);
    expect(top[1].typicalMonth.minor).toBe(usd(30).minor);
  });

  it("ignores everything past the ledger's coverage", () => {
    const rows = [...groceries, tx("2026-07-08", "SAFEWAY GROCERY", -9000)];
    const s = analyseSpending(ledger(rows, "2026-06-30"), undefined, [], "USD");
    expect(s.to).toBe("2026-06-30");
    expect(s.outflows.some((o) => o.txn.date > "2026-06-30")).toBe(false);
  });

  it("has nothing to say about an empty ledger rather than inventing a zero month", () => {
    const s = analyseSpending(ledger([]), undefined, [], "USD");
    expect(s.outflows).toEqual([]);
    expect(s.categories).toEqual([]);
    expect(s.variableMonthly.minor).toBe(0);
    expect(s.monthsObserved).toBe(0);
  });
});
